//! Actual born-enforced factories, owned metadata stores and pinned TLS.
//! Election barriers are generated by the FSM; replication delivery alone is
//! withheld until the actual finite startup heartbeat is invoked.
use super::*;
use std::{fs, time::Instant};

fn budget() -> CancellationToken {
    CancellationToken::uncancelable().child_with_deadline(Instant::now() + Duration::from_secs(5))
}

#[test]
fn native_initial_metadata_actual_tls_barrier_backlog_advances_beyond_first_batch() {
    let summary_root = if let Some(root) = std::env::var_os("BICDB_TEST_EVIDENCE_ROOT") {
        fs::create_dir_all(&root).unwrap();
        tempfile::Builder::new()
            .prefix("native-metadata-heartbeat-backlog-")
            .tempdir_in(root)
            .unwrap()
    } else {
        tempfile::tempdir().unwrap()
    }
    .keep();
    let mut fixture = Fixture::new();
    // Keep native files and generated test TLS keys PRIVATE, outside the
    // optional public evidence subtree. Only sanitized factual traces go there.
    fixture._root.disable_cleanup(true);
    eprintln!(
        "NATIVE_HEARTBEAT_BACKLOG_PRIVATE_ROOT {}",
        fixture._root.path().display()
    );
    eprintln!(
        "NATIVE_HEARTBEAT_BACKLOG_SUMMARY {}",
        summary_root.display()
    );
    let configuration = fixture.hosts[0]
        .observe_initial_configuration(&budget())
        .unwrap();
    let permits = fixture
        .hosts
        .iter()
        .map(|host| {
            host.prepare_common_initial_configuration(&configuration, &budget())
                .unwrap()
        })
        .collect::<Vec<_>>();
    let launches = fixture
        .hosts
        .iter_mut()
        .zip(&permits)
        .map(|(host, permit)| host.finish_initial_consensus(permit, &budget()).unwrap())
        .collect::<Vec<_>>();
    let _listeners = launches
        .iter()
        .enumerate()
        .map(|(i, launch)| {
            launch
                .start_metadata_listener(fixture.networks[i].clone(), &budget())
                .unwrap()
        })
        .collect::<Vec<_>>();
    let app_wal_before = launches
        .iter()
        .map(|launch| {
            let db = launch.seed.database.read();
            let stats = db.tx_log_handle().stats();
            (stats.written_seq, stats.commits_written)
        })
        .collect::<Vec<_>>();
    let mut trace = Vec::new();
    // Each term is a genuine election with the candidate's real persisted
    // self-vote plus an actual pinned TLS response from node1. No Append is
    // sent in these 17 rounds: this is the declared replication fault schedule.
    for expected_term in 1..=17 {
        let request = launches[0].metadata.lock().start_election().unwrap();
        assert_eq!(request.term, expected_term);
        let reply = launches[0]
            .transport
            .request_metadata_vote_cancellable(&node(1), request.clone(), &budget())
            .unwrap();
        assert!(reply.vote_granted);
        assert_eq!(reply.term, request.term);
        assert_eq!(reply.voter_id, node(1));
        let votes = BTreeSet::from([request.candidate_id.clone(), reply.voter_id.clone()]);
        let status = {
            let mut metadata = launches[0].metadata.lock();
            metadata.become_leader(&votes).unwrap();
            metadata.status()
        };
        assert_eq!(status.last_log_index, expected_term);
        assert_eq!(status.commit_index, 0);
        trace.push(
            serde_json::json!({"event":"actual_TLS_election_append_withheld",
            "request":request,"reply":reply,"leader_status":status}),
        );
    }
    let before = launches
        .iter()
        .map(|launch| launch.metadata.lock().status())
        .collect::<Vec<_>>();
    assert_eq!(before[0].last_log_index, 17);
    assert_eq!(before[1].last_log_index, 0);
    assert_eq!(before[2].last_log_index, 0);
    // The current-term read anchor must stay closed while no actual current
    // barrier has committed. HostMQ is DATA only, never writer/read permission.
    let early_mq = launches[0].transport.acquire_host_metadata_observation(
        &node(0),
        Uuid::now_v7(),
        Duration::from_secs(5),
        &budget(),
    );
    assert!(
        early_mq.is_err(),
        "uncommitted term17 must not issue fresh HostMQ"
    );
    let generated_before = launches[0]
        .metadata
        .lock()
        .append_request_from(1, 16)
        .unwrap();
    assert_eq!(generated_before.entries.len(), 16);
    assert_eq!(generated_before.entries.last().unwrap().index, 16);
    let first = launches[0].heartbeat_initial_metadata(&budget());
    let after_first = launches
        .iter()
        .map(|launch| launch.metadata.lock().status())
        .collect::<Vec<_>>();
    let second = launches[0].heartbeat_initial_metadata(&budget());
    let after_second = launches
        .iter()
        .map(|launch| launch.metadata.lock().status())
        .collect::<Vec<_>>();
    let generated_after = launches[0]
        .metadata
        .lock()
        .append_request_from(1, 16)
        .unwrap();
    // All real peers are healthy now. Call the real startup election/recovery
    // entry point, which must commit its OWN fresh barrier before success.
    let recovered = launches[0].elect_initial_metadata(&budget());
    let final_status = launches
        .iter()
        .map(|launch| launch.metadata.lock().status())
        .collect::<Vec<_>>();
    let final_mq = launches[0].transport.acquire_host_metadata_observation(
        &node(0),
        Uuid::now_v7(),
        Duration::from_secs(5),
        &budget(),
    );
    let app_wal_after = launches
        .iter()
        .map(|launch| {
            let db = launch.seed.database.read();
            assert!(!db.commit_admission_ready());
            let stats = db.tx_log_handle().stats();
            (stats.written_seq, stats.commits_written)
        })
        .collect::<Vec<_>>();
    let summary = serde_json::json!({
        "trace":trace,"before":before,"generated_before":generated_before,
        "first_heartbeat":first.as_ref().map(|_| "ok").map_err(ToString::to_string),
        "after_first":after_first,
        "second_heartbeat":second.as_ref().map(|_| "ok").map_err(ToString::to_string),
        "after_second":after_second,"generated_after":generated_after,
        "recovery":recovered.as_ref().map_err(ToString::to_string),
        "final_status":final_status,
        "pre_commit_HostMQ":early_mq.as_ref().map(|_| "observed").map_err(ToString::to_string),
        "final_HostMQ":final_mq.as_ref().map(|_| "observed").map_err(ToString::to_string),
        "application_wal_before":app_wal_before,"application_wal_after":app_wal_after,
        "scope":"actual local native-host/TLS metadata orchestration only; no data ACK/Strong/automatic scheduler/VM/Azure claim",
    });
    crate::storage::write_atomic(
        &summary_root.join("heartbeat-backlog-result.json"),
        &serde_json::to_vec_pretty(&summary).unwrap(),
        true,
    )
    .unwrap();
    eprintln!("NATIVE_HEARTBEAT_BACKLOG_RESULT {summary}");
    assert_eq!(app_wal_before, app_wal_after);
    assert!(
        recovered.is_ok(),
        "healthy majority cannot recover beyond first16: {recovered:?}; summary {}",
        summary_root.display()
    );
    assert!(
        final_mq.is_ok(),
        "successful recovery still has no actual current-term read anchor"
    );
}
